import {
  cloneDeep as _cloneDeep,
  debounce as _debounce,
  isEqual as _isEqual,
  throttle as _throttle,
  toMerged as _toMerged,
} from "es-toolkit";
import { set as _set } from "es-toolkit/compat";

export type DeepNonNullable<T> = T extends object
  ? { [K in keyof T]-?: DeepNonNullable<NonNullable<T[K]>> }
  : NonNullable<T>;

export type IsPlainObject<T> = T extends object
  ? T extends any[]
    ? false
    : T extends Function
      ? false
      : true
  : false;

export type NestedKeys<T> = {
  [K in keyof T]: K extends string
    ? IsPlainObject<T[K]> extends true
      ? K | `${K}.${NestedKeys<T[K]>}`
      : K
    : never;
}[keyof T];

export const attempt = async <T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> =>
  retries > 0
    ? await fn().catch(async (error) => {
        console.error(`Function failed, error: ${error}. Retrying after ${delay}ms...`);

        return sleep(delay).then(() => attempt(fn, retries - 1, delay));
      })
    : fn();

export const convertNestedKeys = (updates: Record<string, any>): Record<string, any> => {
  const result: Record<string, any> = {};

  for (const [key, value] of Object.entries(updates)) {
    const parts = key.split(".");
    let nested = result;

    if (parts.some((part) => ["__proto__", "constructor", "prototype"].includes(part)))
      throw new Error(`Unsafe nested key: ${key}`);

    for (const [index, part] of parts.entries()) {
      if (index === parts.length - 1) nested[part] = value;
      else {
        if (!Object.hasOwn(nested, part) || !isPlainObject(nested[part])) nested[part] = {};

        nested = nested[part];
      }
    }
  }

  return result;
};

export const debounce = _debounce;

export const deepClone = _cloneDeep;

export type DeepPartial<T> = { [P in keyof T]?: DeepPartial<T[P]> };

export const deepMerge = _toMerged;

export const handleErrors = async <T>(
  fn: () => Promise<T>,
): Promise<{ data?: T; error?: string; success: boolean }> => {
  try {
    return { data: await fn(), success: true };
  } catch (err) {
    const errorStr = err?.message ?? String(err);

    console.error(errorStr);

    return { error: errorStr, success: false };
  }
};

export const isDeepEqual = _isEqual;

export const isObject = (item: any): boolean =>
  item && typeof item === "object" && !Array.isArray(item);

export const isPlainObject = (value: unknown): value is Record<string, any> => {
  if (!value || typeof value !== "object") return false;

  const proto = Object.getPrototypeOf(value);

  return proto === Object.prototype || proto === null;
};

export const mergePreset = <T>(preset: Partial<T>, props: T): T => {
  const merge = (presetValue: any, propValue: any): any => {
    if (propValue === undefined) return presetValue;

    if (!isPlainObject(presetValue) || !isPlainObject(propValue)) return propValue;

    const result: Record<string, any> = { ...presetValue };

    for (const key of Object.keys(propValue)) result[key] = merge(presetValue[key], propValue[key]);

    return result;
  };

  return merge(preset, props);
};

export const rng = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

export const setObj = _set;

export const sleep = (min: number, max?: number) =>
  new Promise((resolve) => setTimeout(resolve, max > 0 ? rng(min, max) : min));

export const throttle = _throttle;

export const uuid = () => crypto.randomUUID();
